import asyncio,json,os,re,threading
from pathlib import Path
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from urllib.parse import urlsplit,unquote,urljoin
from xml.etree import ElementTree as ET
from bs4 import BeautifulSoup
from playwright.async_api import async_playwright
from outbound_nofollow import external as is_external, run as check_outbound
manifest=json.loads(Path('.release/url-manifest.json').read_text())
pages=[e['file'] for e in manifest['entries']]
routes={e['file']:e['path'] for e in manifest['entries']}
assert len(pages)==108 and len(set(pages))==108
assert set(pages)=={p.name for p in Path('.').glob('*.htm*') if p.suffix in ('.html','.htm')}
knowledge=set(json.loads(Path('.github/qa/pages.json').read_text()))
tools=set(pages)-knowledge
assert len(knowledge)==91 and len(tools)==17
base=manifest['production']
assert len(set(routes.values()))==len(pages), 'Duplicate production routes'
expected_urls={base+path for path in routes.values()}
sitemap_locs=[node.text for node in ET.parse('.release/sitemap.xml').getroot().findall('{http://www.sitemaps.org/schemas/sitemap/0.9}url/{http://www.sitemaps.org/schemas/sitemap/0.9}loc')]
assert len(sitemap_locs)==len(expected_urls) and set(sitemap_locs)==expected_urls, 'Release sitemap does not match manifest'
route_set=set(routes.values())
internal_hosts={urlsplit(base).hostname,urlsplit(manifest['preview']).hostname,'levenshtein.net'}
def canonical_url(value):
 return value+'/' if value==base else value
ai_pattern=re.compile(r"\b(?:as an ai language model|generated by chatgpt|i cannot browse|lorem ipsum|insert (?:title|content|keyword) here)\b",re.I)
dev_pattern=re.compile(r"PREVIEW ĐẶT TRƯỚC FONTS THEO YÊU CẦU|FONTS SAU PREVIEW, 1 CỘT")

out=Path('qa-report');out.mkdir(exist_ok=True)
issues=[]; results=[]
mode=os.environ.get('QA_MODE','static')
engine=os.environ.get('QA_ENGINE','chromium')
sizes=json.loads(os.environ.get('QA_SIZES','[]'))
expected=len(pages)*len(sizes) if mode=='browser' else len(pages)
def checkpoint():
 report=dict(mode=mode,engine=engine,pages=len(pages),expected=expected,completed=len(results),passed=sum(r['passed'] for r in results),issues=issues,results=results)
 tmp=out/'report.tmp';tmp.write_text(json.dumps(report,indent=2));tmp.replace(out/'report.json')
 print('QA PROGRESS',len(results),'/',expected,flush=True)
def issue(page,kind,detail): issues.append(dict(page=page,kind=kind,detail=detail))
class Handler(SimpleHTTPRequestHandler):
 def translate_path(self,path):
  p=super().translate_path(path)
  if not os.path.exists(p) and os.path.isfile(p+'.html'): return p+'.html'
  return p
 def log_message(self,*args): pass
server=ThreadingHTTPServer(('127.0.0.1',0),Handler)
threading.Thread(target=server.serve_forever,daemon=True).start()
origin='http://127.0.0.1:'+str(server.server_port)
for name in (pages if mode=='static' else []):
 before=len(issues)
 p=Path(name)
 if not p.is_file():
  issue(name,'missing','file');results.append(dict(page=name,passed=False));checkpoint();continue
 source=p.read_text(encoding='utf-8')
 _, outbound=check_outbound(source,False)
 if outbound['missing_after']: issue(name,'outbound_nofollow',str(outbound['missing_after'])+' missing: '+str(outbound['missing_examples']))
 s=BeautifulSoup(source,'html.parser')
 for selector in ['title','meta[name=description]','meta[name=viewport]','link[rel=canonical]','h1','main']:
  n=len(s.select(selector))
  if n!=1: issue(name,'markup',selector+': '+str(n))
 canon=s.select_one('link[rel=canonical]')
 if not canon or (canonical_url(canon.get('href','')) != base+routes[name]): issue(name,'canonical','does not match production route')
 robots=s.select_one('meta[name=robots]')
 if not robots or not {'noindex','nofollow'}<=set(x.strip().lower() for x in robots.get('content','').split(',')): issue(name,'robots','preview directives absent')
 if not s.select('script[type="application/ld+json"]'): issue(name,'schema','missing JSON-LD')
 main=s.select_one('main')
 if main and ai_pattern.search(main.get_text(' ',strip=True)): issue(name,'content','possible prompt/placeholder residue')
 if dev_pattern.search(source): issue(name,'source','development comment residue')
 if name in tools:
  alt=s.select('link[rel=alternate][hreflang]')
  actual={a.get('href','') for a in alt}
  wanted={base+routes[t] for t in tools}
  if len(alt)!=17 or len({a.get('hreflang') for a in alt})!=17 or actual!=wanted: issue(name,'hreflang','incomplete reciprocal locale cluster')
  if not s.select_one('#lf194-root'): issue(name,'tool','missing application root')
 for tag in s.select('img[src],script[src],link[rel=stylesheet][href],link[rel=icon][href]'):
  value=tag.get('src') or tag.get('href') or ''
  u=urlsplit(value)
  if u.hostname and u.hostname not in ('www.levenshtein.net','levenshtein.net','levenshteinv2.github.io'): continue
  if u.scheme and u.scheme not in ('http','https'): continue
  if not u.path or u.path.startswith('data:'): continue
  dest=Path(unquote(u.path.lstrip('/'))) if u.path.startswith('/') else p.parent/unquote(u.path)
  if not dest.is_file(): issue(name,'asset_not_in_checkout',value[:250])
 for a in s.select('a[href]'):
  h=a.get('href','')
  u=urlsplit(h)
  if u.hostname in ('www.levenshtein.net','levenshtein.net','levenshteinv2.github.io') and u.path.endswith('.html'): issue(name,'route_alias',h)
  if not u.scheme and not u.netloc and u.path.endswith('.html'): issue(name,'route_alias',h)
  if u.hostname=='levenshteinv2.github.io': issue(name,'preview_link',h)
 if s.select('a.__cf_email__'): issue(name,'contact','Cloudflare protected email snapshot is not a working contact')
 for tag in s.select('meta[content]'):
  if 'null.gif' in tag.get('content',''): issue(name,'metadata','null.gif')
 for a in s.select('a[href]'):
  h=a['href'];u=urlsplit(h)
  resolved=urlsplit(urljoin(base+routes[name],h))
  if resolved.scheme not in ('http','https') or resolved.hostname not in internal_hosts: continue
  target=unquote(resolved.path) or '/'
  if target not in route_set:
   # Preserve intentional file downloads; do not accept an HTML alias as a substitute for a public route.
   asset=Path(target.lstrip('/'))
   if not asset.is_file() or asset.suffix.lower() in ('.html','.htm'): issue(name,'unmapped_internal_route',h)
 for tag in s.select('script[type="application/ld+json"]'):
  try: json.loads(tag.get_text())
  except Exception: issue(name,'schema','invalid JSON')
 results.append(dict(page=name,passed=len(issues)==before));checkpoint()
async def run():
 async with async_playwright() as pw:
  for _ in range(1):
   browser=await getattr(pw,engine).launch()
   sem=asyncio.Semaphore(4)
   async def check(name,w,h):
    async with sem:
     context=await browser.new_context(viewport={'width':w,'height':h})
     await context.route('**/*',lambda route: route.continue_() if route.request.url.startswith(origin+'/') else route.abort())
     page=await context.new_page()
     errors=[]
     page.on('pageerror',lambda e:errors.append(str(e)))
     try:
      response=await page.goto(origin+routes[name],wait_until='domcontentloaded',timeout=8000)
      await page.evaluate('Promise.race([document.fonts.ready,new Promise(r=>setTimeout(r,1000))])')
      data=await page.evaluate("""() => ({width:document.documentElement.scrollWidth,viewport:innerWidth,overflow:[...document.querySelectorAll('body *')].filter(e=>{const r=e.getBoundingClientRect();return r.width>0 && r.right>innerWidth+2 && !e.closest('.ux-scroll')}).slice(0,8).map(e=>e.tagName+'.'+String(e.className).slice(0,80))})""")
      failures=[]
      if not response or response.status!=200: failures.append('HTTP '+str(response.status if response else None))
      if page.url!=origin+routes[name]: failures.append('Unexpected route redirect '+page.url)
      if data['width']>w+2: failures.append('horizontal overflow '+str(data))
      # Check rendered anchors too; use the actual href attribute, not the local test origin.
      anchors=await page.locator('a[href], area[href]').evaluate_all("els => els.map(e => ({href:e.getAttribute('href'),rel:e.getAttribute('rel') || ''}))")
      missing=[a['href'] for a in anchors if is_external(a['href'] or '') and 'nofollow' not in a['rel'].lower().split()]
      if missing: failures.append('outbound nofollow missing: '+str(missing[:10]))
      if w in (390,1440):
       try:
        menu=page.locator('.ux-tool-dropdown > summary')
        if await menu.count()!=1: failures.append('missing or duplicate tool dropdown')
        else:
         header=page.locator('.ux-header').first
         before=await header.bounding_box()
         await menu.click(timeout=3000)
         opened=page.locator('.ux-tool-dropdown[open] .ux-tool-menu')
         await opened.wait_for(state='visible',timeout=3000)
         after=await header.bounding_box()
         box=await opened.bounding_box()
         if not before or not after or abs(before['height']-after['height'])>3: failures.append('dropdown changes header height')
         if not box or box['x'] < -2 or box['x']+box['width']>w+2: failures.append('dropdown outside viewport')
         if await opened.locator('.ux-tool-menu-grid a').count()!=17: failures.append('dropdown locale count')
         await menu.click(timeout=3000)
       except Exception as e: failures.append('navigation smoke: '+str(e))
       if name in tools:
        try:
         await page.locator('.lf-tab[data-tab="quick"]').click(timeout=3000)
         field=page.locator('#quick-input')
         first=page.locator('#quick-grid .lf-font-styled').first
         await first.wait_for(state='visible',timeout=4000)
         old_text=await first.inner_text()
         await field.fill('QA2026')
         await page.wait_for_function("(old) => {const x=document.querySelector('#quick-grid .lf-font-styled'); return x && x.textContent.trim() && x.textContent.trim()!==old.trim()}",arg=old_text,timeout=4000)
         if engine=='chromium':
          await context.grant_permissions(['clipboard-read','clipboard-write'])
          expected_text=await first.inner_text()
          await first.click(timeout=3000)
          copied=await page.evaluate('navigator.clipboard.readText()')
          if copied.strip()!=expected_text.strip(): failures.append('quick style clipboard mismatch')
        except Exception as e: failures.append('tool quick conversion smoke: '+str(e))
      failures+=errors
      for f in failures: issue(name,engine+' '+str(w),f)
      if failures and len(list(out.glob('*.png')))<40: await page.screenshot(path=str(out/(name+'-'+engine+'-'+str(w)+'.png')),timeout=5000)
      results.append(dict(page=name,engine=engine,width=w,passed=not failures))
     except Exception as e:
      issue(name,engine+' '+str(w),str(e));results.append(dict(page=name,engine=engine,width=w,passed=False))
     finally:
      checkpoint()
      try: await asyncio.wait_for(context.close(),timeout=5)
      except Exception: pass
   for n in pages:
    batch=await asyncio.gather(*(asyncio.wait_for(check(n,w,h),timeout=25) for w,h in sizes),return_exceptions=True)
    for (w,h),value in zip(sizes,batch):
     if isinstance(value,BaseException):
      issue(n,engine+' '+str(w),repr(value))
      if not any(r.get('page')==n and r.get('width')==w for r in results): results.append(dict(page=n,engine=engine,width=w,passed=False))
    checkpoint()
   await browser.close()
try:
 if mode=='browser': asyncio.run(run())
finally:
 checkpoint()
 print('QA SUMMARY',json.dumps(dict(expected=expected,completed=len(results),passed=sum(r['passed'] for r in results),issues=len(issues))),flush=True)
 for i in issues[:100]: print('QA ISSUE',json.dumps(i),flush=True)
if issues or len(results)!=expected: raise SystemExit(1)
